def managers():
    """Every app and action; every page, except deleting staff and changing roles and groups (owners do that)."""
    out = APPS + ACTIONS
    for page, levels in PAGES.items():
        if page in ("roles", "groups"):
            levels = "v"
        elif page == "staff":
            levels = "ve"
        out += [f"admin.{page}.{LEVEL[x]}" for x in levels]
    return out


